/* 
  NGINX acting as a simple API Gateway 
*/

server {
    listen 80;
    server_name api.mycompany.com;

    # All auth traffic goes to the Node.js Auth Service on port 4000
    location /auth/ {
        proxy_pass http://10.0.0.1:4000/;
    }

    # All billing traffic goes to the Python Billing Service on port 5000
    location /billing/ {
        proxy_pass http://10.0.0.2:5000/;
    }
}
